<?php require '_header.php';$page_title='Destinations';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'';if($action==='delete'){$q=$pdo->prepare('DELETE FROM destinations WHERE id=?');try{$q->execute([(int)$_POST['id']]);flash('Destination deleted.');}catch(PDOException $e){flash('Cannot delete a destination with existing bookings.','error');}redirect('destinations.php');}
$name=trim($_POST['name']??'');$loc=trim($_POST['location']??'');$desc=trim($_POST['description']??'');$price=(float)($_POST['price']??0);$img=trim($_POST['image_url']??'');$featured=isset($_POST['featured'])?1:0;$id=(int)($_POST['id']??0);if($name&&$loc&&$desc&&$price>=0&&filter_var($img,FILTER_VALIDATE_URL)&&in_array(parse_url($img,PHP_URL_SCHEME),['http','https'],true)){if($id){$q=$pdo->prepare('UPDATE destinations SET name=?,location=?,description=?,price=?,image_url=?,featured=? WHERE id=?');$q->execute([$name,$loc,$desc,$price,$img,$featured,$id]);flash('Destination updated.');}else{$q=$pdo->prepare('INSERT INTO destinations(name,location,description,price,image_url,featured) VALUES(?,?,?,?,?,?)');$q->execute([$name,$loc,$desc,$price,$img,$featured]);flash('Destination added.');}}else flash('Complete all fields and provide a valid http/https image URL.','error');redirect('destinations.php');}
$edit=null;if(isset($_GET['edit'])){$q=$pdo->prepare('SELECT * FROM destinations WHERE id=?');$q->execute([(int)$_GET['edit']]);$edit=$q->fetch();}$rows=$pdo->query('SELECT * FROM destinations ORDER BY id DESC')->fetchAll();?><div class="admin-top"><div><span class="eyebrow">CONTENT MANAGEMENT</span><h1>Destinations & pricing</h1><p class="muted">Edit names, photos, descriptions and per-person prices.</p></div></div><div class="panel" style="margin-top:0"><h2 style="font-size:22px"><?=$edit?'Edit destination':'Add destination'?></h2><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=(int)($edit['id']??0)?>"><div class="form-grid"><div class="field"><label>Destination name</label><input name="name" required value="<?=e($edit['name']??'')?>"></div><div class="field"><label>Location</label><input name="location" required value="<?=e($edit['location']??'')?>"></div><div class="field"><label>Price per person (INR)</label><input type="number" name="price" min="0" step="0.01" required value="<?=e((string)($edit['price']??''))?>"></div><div class="field"><label>Image URL (http/https)</label><input type="url" name="image_url" required value="<?=e($edit['image_url']??'')?>"></div></div><div class="field"><label>Description</label><textarea name="description" required><?=e($edit['description']??'')?></textarea></div><div class="field"><label><input type="checkbox" name="featured" <?=!empty($edit['featured'])?'checked':''?>> Featured destination</label></div><button class="btn btn-primary"><?= $edit?'Save changes':'Add destination'?> →</button> <?php if($edit):?><a class="btn" href="destinations.php">Cancel</a><?php endif;?></form></div><div class="table-wrap"><table><tr><th>Image / destination</th><th>Price</th><th>Featured</th><th>Actions</th></tr><?php foreach($rows as $r):?><tr><td><img src="<?=e($r['image_url'])?>" alt="" style="width:76px;height:55px;object-fit:cover;border-radius:7px"><b><?=e($r['name'])?></b><br><small><?=e($r['location'])?></small></td><td>₹<?=number_format((float)$r['price'])?></td><td><?=$r['featured']?'Yes':'No'?></td><td><a class="small-btn" href="destinations.php?edit=<?=$r['id']?>">Edit</a> <form method="post" style="display:inline" onsubmit="return confirm('Delete this destination?')"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=$r['id']?>"><input type="hidden" name="action" value="delete"><button class="small-btn danger">Delete</button></form></td></tr><?php endforeach;?></table></div><?php require '_footer.php';?>
